-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Marketing from cells/IMPORT Marketing.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/IMPORT Marketing.csv
INSERT INTO "IMPORT Marketing" SELECT coalesce(k0."Brand", fpabench_error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Country", fpabench_error('cells name a member Country does not have: ' || c."Country")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Country" k1 ON k1.name = c."Country" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4
ON CONFLICT ("Brand", "Country", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT Marketing";
